-- Zul'Gurub: the Heart of Hakkar is creature 92005, as in the CoA combat log of 2026-08-02 and the
-- client creature cache (rank 3, model 28887, HealthModifier 17.55, ManaModifier 1.755; hostile per
-- db.exil.es). boss_hakkar_coa summons it instead of the stand-in 9780022 from 14_zg.sql.
DROP TEMPORARY TABLE IF EXISTS `zg_heart`;
CREATE TEMPORARY TABLE `zg_heart` AS SELECT * FROM `creature_template` WHERE `entry` = 15069;
UPDATE `zg_heart` SET `entry` = 92005;
INSERT INTO `creature_template` SELECT * FROM `zg_heart`
ON DUPLICATE KEY UPDATE `entry` = `creature_template`.`entry`;
DROP TEMPORARY TABLE `zg_heart`;
UPDATE `creature_template` SET `name` = 'Heart of Hakkar', `difficulty_entry_1` = 0, `difficulty_entry_2` = 0,
    `difficulty_entry_3` = 0, `minlevel` = 63, `maxlevel` = 63, `faction` = 28, `rank` = 3, `unit_flags` = 0,
    `AIName` = '', `HealthModifier` = 17.55, `ManaModifier` = 1.755, `lootid` = 0, `pickpocketloot` = 0,
    `skinloot` = 0, `ScriptName` = 'npc_heart_of_hakkar_coa', `VerifiedBuild` = 0
 WHERE `entry` = 92005;

DELETE FROM `creature_template_model` WHERE `CreatureID` = 92005;
INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`) VALUES
(92005, 0, 28887, 1, 1, 0);

-- Zul'Gurub creature corrections from the CoA client creature cache: elite rank, ManaModifier and
-- the Sacrificed Troll display. The Zul'Gurub Trigger (14758) stays normal.
UPDATE `creature_template` SET `rank` = 1 WHERE `entry` IN (11360, 11368, 11387, 11388, 11389, 11390, 11391, 14826);

UPDATE `creature_template` SET `ManaModifier` = 1.35 WHERE `entry` IN (11339, 11340, 11830, 11831, 14825);
UPDATE `creature_template` SET `ManaModifier` = 0.3375 WHERE `entry` = 11388;
UPDATE `creature_template` SET `ManaModifier` = 0.65 WHERE `entry` IN (14883, 15111);

UPDATE `creature_template_model` SET `CreatureDisplayID` = 27651 WHERE `CreatureID` = 14826 AND `Idx` = 0;

-- Spawn 51391 in the formation led by 51388 is a Hakkari Shadowcaster live, not a Soulflayer.
UPDATE `creature` SET `id` = 11338, `equipment_id` = 1 WHERE `guid` = 51391;

-- Zul'Gurub access on CoA: level 60 on Normal, Heroic, Mythic and Ascended (MapDifficulty 67-70).
-- rev_20260930_99_ASC_northshire_revamp.sql flattens every map-309 spawnMask to 1, which leaves the
-- three new difficulties empty, so all spawns go back on the four difficulty bits.
UPDATE `dungeon_access_template` SET `min_level` = 60, `comment` = 'Zul\'Gurub (Normal)' WHERE `id` = 20;
DELETE FROM `dungeon_access_template` WHERE `map_id` = 309 AND `difficulty` IN (1, 2, 3);
INSERT INTO `dungeon_access_template` (`map_id`, `difficulty`, `min_level`, `max_level`, `min_avg_item_level`, `comment`) VALUES
(309, 1, 60, 0, 0, 'Zul\'Gurub (Heroic)'),
(309, 2, 60, 0, 0, 'Zul\'Gurub (Mythic)'),
(309, 3, 60, 0, 0, 'Zul\'Gurub (Ascended)');

UPDATE `creature` SET `spawnMask` = 15 WHERE `map` = 309;
UPDATE `gameobject` SET `spawnMask` = 15 WHERE `map` = 309;

-- Zul'Gurub quests as in the CoA client quest cache: Zandalar Tribe reputation comes from the
-- QuestFactionReward index (+250/+350/+500) instead of the 10000/15000/20000 override, The Hero's Brand,
-- the class enchant and Savage Guard quests open at level 10 and The Heart of Hakkar at level 60.
UPDATE `quest_template` SET `RewardFactionOverride1` = 0 WHERE `RewardFactionID1` = 270 AND `RewardFactionOverride1` <> 0;
UPDATE `quest_template` SET `MinLevel` = 10 WHERE `ID` IN (8048, 8184, 8185, 8186, 8187, 8188, 8189, 8190, 8191, 8192, 9208, 9209, 9210);
UPDATE `quest_template` SET `MinLevel` = 60 WHERE `ID` = 8183;

-- Zul'Gurub: scripts for the zealots' and Chained Spirits' Ascension dummy spells (Sinister Strike, Blind,
-- Storm Shield and its charges, Resurrection).
DELETE FROM `spell_script_names`
WHERE `spell_id` IN (2118250, 2118252) AND `ScriptName` = 'spell_thekal_coa_zath_strike';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(2118250, 'spell_thekal_coa_zath_strike'),
(2118252, 'spell_thekal_coa_zath_strike');

DELETE FROM `spell_script_names` WHERE `spell_id` = 2118261 AND `ScriptName` = 'spell_thekal_coa_storm_shield';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(2118261, 'spell_thekal_coa_storm_shield');

DELETE FROM `spell_script_names` WHERE `spell_id` = 2118262 AND `ScriptName` = 'spell_thekal_coa_storm_shield_charge';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(2118262, 'spell_thekal_coa_storm_shield_charge');

DELETE FROM `spell_script_names` WHERE `spell_id` = 2118426 AND `ScriptName` = 'spell_mandokir_coa_resurrection';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(2118426, 'spell_mandokir_coa_resurrection');

-- Zul'Gurub: Jin'do's Powerful Healing Ward casts Ascension's Healing Stream (2118504) from his script instead of
-- its stock heal, so it gets a passive AI; the stream heals a share of his missing health every second.
UPDATE `creature_template` SET `AIName` = 'NullCreatureAI', `ScriptName` = '' WHERE `entry` = 14987;

DELETE FROM `spell_script_names` WHERE `spell_id` = 2118504 AND `ScriptName` = 'spell_jindo_coa_healing_stream';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(2118504, 'spell_jindo_coa_healing_stream');
